"use strict";(self.webpackChunklasso=self.webpackChunklasso||[]).push([[4787],{86050:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"icst25","metadata":{"permalink":"/web/blog/icst25","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-04-14-icst25.mdx","source":"@site/blog/2025-04-14-icst25.mdx","title":"Presentation Slides - ICST 2025","description":"We recently presented our journal article  as part of ICST25\'s Journal-First track @ ICST\'25.","date":"2025-04-14T00:00:00.000Z","tags":[],"readingTime":0.34,"hasTruncateMarker":false,"authors":[{"name":"Marcus Kessel","title":"LASSO Maintainer","url":"https://www.wim.uni-mannheim.de/atkinson/team/dr-marcus-kessel/","imageURL":"https://www.wim.uni-mannheim.de/media/_processed_/b/2/csm_Kessel_profile_e602ea80ee.jpeg","key":"mkessel","page":null}],"frontMatter":{"slug":"icst25","title":"Presentation Slides - ICST 2025","authors":["mkessel"],"tags":[]},"unlisted":false,"nextItem":{"title":"Preview of LSLFlow","permalink":"/web/blog/lslflow"}},"content":"We recently presented our journal article  as part of ICST25\'s Journal-First track @ ICST\'25.\\n\\n\\n\\n\\nWe\'re excited to share that we recently presented our journal article, <a href=\\"https://www.sciencedirect.com/science/article/pii/S0164121224000141\\">\\"Promoting Open Science in Test-driven Software Experiments\\"</a> as part of the Journal-First track at <a href=\\"https://conf.researchr.org/home/icst-2025\\">ICST\'25</a>! This track provides a unique opportunity to showcase research that has already been published in a peer-reviewed journal. You can find our presentation slides <a href=\\"/web/pdfviewer?f=ICST_JF_talk_02.04.25.pdf\\">here</a>."},{"id":"lslflow","metadata":{"permalink":"/web/blog/lslflow","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-03-31-lslflow.mdx","source":"@site/blog/2025-03-31-lslflow.mdx","title":"Preview of LSLFlow","description":"A first visual representation of a graph editor for designing and managing LSL pipelines is now available.","date":"2025-03-31T00:00:00.000Z","tags":[],"readingTime":0.495,"hasTruncateMarker":false,"authors":[{"name":"Marcus Kessel","title":"LASSO Maintainer","url":"https://www.wim.uni-mannheim.de/atkinson/team/dr-marcus-kessel/","imageURL":"https://www.wim.uni-mannheim.de/media/_processed_/b/2/csm_Kessel_profile_e602ea80ee.jpeg","key":"mkessel","page":null}],"frontMatter":{"slug":"lslflow","title":"Preview of LSLFlow","authors":["mkessel"],"tags":[]},"unlisted":false,"prevItem":{"title":"Presentation Slides - ICST 2025","permalink":"/web/blog/icst25"},"nextItem":{"title":"Preview of Arena Test Driver for Python","permalink":"/web/blog/arena-python"}},"content":"A first visual representation of a graph editor for designing and managing LSL pipelines is now available.\\n\\n### Key Features\\n\\n* Visual Pipeline Design: Design LSL pipelines visually using a graph-based interface.\\n* Interactive Preview: View your pipeline design in action with an interactive preview feature.\\n\\n###  Development Status\\n\\nThe project is actively developed by **David Cebulla**, a business informatics student at the University of Mannheim, as part of his Bachelor Thesis. The goal is to translate visual graph representations into corresponding LSL pipelines efficiently.\\n\\n### Preview\\n\\nVisit the Project Website: Explore the preview version of LSLFlow here: [LSLFlow](https://softwareobservatorium.github.io/lslflow/)"},{"id":"arena-python","metadata":{"permalink":"/web/blog/arena-python","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-02-17-arena-python.mdx","source":"@site/blog/2025-02-17-arena-python.mdx","title":"Preview of Arena Test Driver for Python","description":"We\'re excited to share that our efforts to support Python in the LASSO platform are gaining momentum! A first version of the arena test driver for Python is now available on GitHub, accessible at https://github.com/SoftwareObservatorium/arena-python.","date":"2025-02-17T00:00:00.000Z","tags":[],"readingTime":0.835,"hasTruncateMarker":false,"authors":[{"name":"Marcus Kessel","title":"LASSO Maintainer","url":"https://www.wim.uni-mannheim.de/atkinson/team/dr-marcus-kessel/","imageURL":"https://www.wim.uni-mannheim.de/media/_processed_/b/2/csm_Kessel_profile_e602ea80ee.jpeg","key":"mkessel","page":null}],"frontMatter":{"slug":"arena-python","title":"Preview of Arena Test Driver for Python","authors":["mkessel"],"tags":[]},"unlisted":false,"prevItem":{"title":"Preview of LSLFlow","permalink":"/web/blog/lslflow"},"nextItem":{"title":"Introducing the New Project Website!","permalink":"/web/blog/new-project-website"}},"content":"We\'re excited to share that our efforts to support Python in the LASSO platform are gaining momentum! A first version of the arena test driver for Python is now available on GitHub, accessible at [https://github.com/SoftwareObservatorium/arena-python](https://github.com/SoftwareObservatorium/arena-python).\\n\\n**Key Features**\\n\\nOur current development includes support for essential data structures used in LASSO:\\n\\n* **LQL**: Our Lasso Query Language (LQL) implementation allows you to represent interfaces in a concise and readable manner.\\n* **SSN**: Sequence sheet notation is also supported, providing a convenient way to work with biological sequences.\\n* **Stimulus Response Matrices**: We\'ve integrated the use of pandas DataFrames to create and manipulate these matrices.\\n\\n**What\'s Next**\\n\\nWe\'re working on integrating our Python support into the LASSO platform, specifically the LSL pipeline language. This will enable you to leverage the full power of LASSO in your Python workflows.\\n\\n**Explore Our Examples**\\n\\nGet hands-on experience with our Python implementation using Jupyter Notebooks:\\n\\n* [https://github.com/SoftwareObservatorium/arena-python/tree/main/notebooks](https://github.com/SoftwareObservatorium/arena-python/tree/main/notebooks)\\n\\nAdditionally, you can explore the system tests for the arena API in our GitHub repository:\\n\\n* [https://github.com/SoftwareObservatorium/arena-python/tree/main/tests](https://github.com/SoftwareObservarium/arena-python/tree/main/tests)"},{"id":"new-project-website","metadata":{"permalink":"/web/blog/new-project-website","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-02-01-new-project-website.mdx","source":"@site/blog/2025-02-01-new-project-website.mdx","title":"Introducing the New Project Website!","description":"Exciting news, everyone! We are thrilled to announce the launch of the brand new website for LASSO, the Large-Scale Software Observatorium for the Dynamic Selection, Analysis and Comparison of Software.","date":"2025-02-01T00:00:00.000Z","tags":[],"readingTime":0.795,"hasTruncateMarker":false,"authors":[{"name":"Marcus Kessel","title":"LASSO Maintainer","url":"https://www.wim.uni-mannheim.de/atkinson/team/dr-marcus-kessel/","imageURL":"https://www.wim.uni-mannheim.de/media/_processed_/b/2/csm_Kessel_profile_e602ea80ee.jpeg","key":"mkessel","page":null}],"frontMatter":{"slug":"new-project-website","title":"Introducing the New Project Website!","authors":["mkessel"],"tags":[]},"unlisted":false,"prevItem":{"title":"Preview of Arena Test Driver for Python","permalink":"/web/blog/arena-python"}},"content":"Exciting news, everyone! We are thrilled to announce the launch of the brand new website for LASSO, the Large-Scale Software Observatorium for the Dynamic Selection, Analysis and Comparison of Software.\\n\\nThe new website features:\\n\\n* A clean and modern design: Easier to navigate and visually appealing.\\n* Detailed project documentation: Get a comprehensive understanding of LASSO\'s features, functionality, and how to use it effectively.\\n* A vibrant community section: Connect with other LASSO users, share your experiences, and contribute to the project\'s growth.\\n\\nRegular blog updates: Stay informed about the latest developments, news, and insights related to LASSO.\\n\\nWith the new website, we aim to:\\n\\n* Make LASSO more accessible to a wider audience.\\n* Foster a stronger sense of community around the project.\\n* Encourage contributions and collaboration from developers and users alike.\\n\\nExplore everything LASSO has to offer. We encourage you to leave your feedback, ask questions, and join the growing community of LASSO users ([Contact Us](/contact))."}]}}')}}]);